import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    H,W=len(g),len(g[0]); bg=g[0][0]
    bars=[]
    for j in range(W):
        col=[g[i][j] for i in range(H)]
        nz=[i for i,v in enumerate(col) if v!=bg]
        if len(nz)>=2 and len({col[i] for i in nz})==1 and (j==0 or j==W-1):
            bars.append((j,nz[0],nz[-1],col[nz[0]]))
    infos=[]
    for j,r0,r1,c in bars:
        marks=[(i,k) for i in range(r0,r1+1) for k in range(W) if g[i][k] not in (bg,c)]
        infos.append((j,r0,r1,c,marks))
    mr=max(infos,key=lambda x:len(x[4])); Or=[x for x in infos if x is not mr][0]
    j0,a0,b0,c0,mk=mr; j1,a1,b1,c1,_=Or
    fillc=g[mk[0][0]][mk[0][1]]
    out=[row[:] for row in g]
    for i,k in mk:
        for kk in range(min(k,j0)+1,max(k,j0)): out[i][kk]=fillc
        out[i][k]=4
    for o in sorted(i-a0 for i,k in mk):
        i=a1+o
        for kk in range(W):
            if kk!=j1: out[i][kk]=fillc
    return out

for p in ['Demo pair 1','Demo pair 2']:
    print(p, transform(G[p+' input'])==G[p+' output'])
print(json.dumps(transform(G['Test input'])))

pred=transform(G['Demo pair 1 input']); exp=G['Demo pair 1 output']
for i,(a,b) in enumerate(zip(pred,exp)):
    if a!=b: print(i,'pred',a); print(i,'exp ',b)
